      "given": "Haber process equilibrium: $N_2(g) + 3H_2(g) \\rightleftharpoons 2NH_3(g)$.",
      "formula": "$K_p = K_c (RT)^{\\Delta n_g}$, where $\\Delta n_g = \\sum n_{products}(g) - \\sum n_{reactants}(g)$.",
