      "given": "Sparingly soluble salt $AgCl$ in the presence of strong electrolyte $NaCl$.",
      "formula": "$AgCl(s) \\rightleftharpoons Ag^+(aq) + Cl^-(aq)$; $K_{sp} = [Ag^+][Cl^-]$.",
