    "question": "Q213. (NEET Medium) A buffer solution is prepared by mixing $0.1\\text{ M } \\text{CH}_3\\text{COOH}$ and $0.1\\text{ M } \\text{CH}_3\\text{COONa}$. Given $pK_a$ of acetic acid is $4.76$, the pH of the buffer solution is:",
