    "question": "Q218. (NEET Medium) According to Le Chatelier's principle, for the exothermic synthesis of ammonia $\\text{N}_2(g) + 3\\text{H}_2(g) \\rightleftharpoons 2\\text{NH}_3(g) + 92.4\\text{ kJ}$, the yield of ammonia is maximized by:",
